const STATUS = { submitting: { es: 'Enviando a SAP', en: 'Submitting to SAP' } };
const lang = $json.language || 'es';
const { _record_index, _record_total } = $json;
// Batch turns (see batch-processing.json's Fan Out Intents) stamp _record_index/_record_total
// on every real record before calling this sub-workflow once per record -- when present, this
// is a batch record's own execution, so report per-record progress instead of the generic
// submitting text. A non-batch call (single form-fill confirm, or a live GET) never carries
// these fields and keeps the original message.
const status_text = (_record_index && _record_total)
  ? (lang === 'en' ? `Processing ${_record_index} of ${_record_total} requests...` : `Procesando ${_record_index} de ${_record_total} solicitudes...`)
  : STATUS.submitting[lang];
return [{ json: { ...$json, status_text } }];

const pipelineDataIn = $('Status Text: Submitting').first().json;
const { active_node_id, intention_nodes, organization, session, sap_operation: callerOperation } = pipelineDataIn;
const activeNode = (intention_nodes || {})[active_node_id] || {};
const { process_definition, form_state } = activeNode;
const integ = organization?.integration || {};
const authDriver = integ.auth_driver || 'b1s';
const connection = authDriver === 'b1s'
  ? { authDriver, baseUrl: integ.base_url, username: session?.user?.username, password: session?.user?.password, companyDB: session?.database }
  : { authDriver, baseUrl: integ.base_url, token: session?.access_token };
// CALL_FUNCTION is a one-off helper call the caller (e.g. generate-document.json) sets
// directly, never derived from a registered process's own api.method -- there's no
// process_definition to derive it FROM (active_node_id is null for this call), so it must be
// preserved as given rather than falling into the GET/POST derivation below.
let operationType;
let serviceName;
if (callerOperation === 'CALL_FUNCTION') {
  operationType = 'CALL_FUNCTION';
  serviceName = '';
} else {
  const method = (process_definition?.api?.method || 'GET').toUpperCase();
  serviceName = process_definition?.api?.service || '';
  if (method === 'GET') {
    const keyDef = process_definition?.query?.key;
    const keyValue = keyDef ? form_state?.[keyDef.id] : null;
    operationType = keyValue !== null && keyValue !== undefined ? 'GET_SINGLE' : 'GET_QUERY';
  } else {
    operationType = 'POST_CREATE';
  }
}
let data = null;
if (operationType === 'POST_CREATE' && Array.isArray(process_definition?.form?.sections)) {
  const payload = {};
  for (const section of process_definition.form.sections) {
    if (section.multiple) {
      const items = form_state[section.id];
      if (Array.isArray(items) && items.length > 0) {
        payload[section.sap_field] = items.map(item => {
          const line = {};
          for (const field of (section.fields || [])) {
            const val = item[field.id];
            if (val !== null && val !== undefined && val !== '') line[field.sap_field] = val;
          }
          return line;
        });
      }
    } else {
      for (const field of (section.fields || [])) {
        const val = form_state[field.id];
        if (val !== null && val !== undefined && val !== '') payload[field.sap_field] = val;
      }
    }
  }
  data = payload;
}
// Speculatively reset the active node's form_state.ready to false before the outcome is
// known -- this used to be a separate Reset Form Not Ready node, run only on a hard
// agent/tool failure. Folded in here and made unconditional: harmless on the success path
// (Compute Execution Outcome's success branch marks the node 'completed' and never reads
// form_state.ready), and covers the graceful-SAP-error path too, which needs the exact
// same reset (Compute Execution Outcome already does its own for that path, so this is a
// redundant no-op there, not a conflict).
const intentionNodes = active_node_id && intention_nodes?.[active_node_id]
  ? { ...intention_nodes, [active_node_id]: { ...activeNode, form_state: { ...(activeNode.form_state || {}), ready: false } } }
  : intention_nodes;
return [{ json: { ...pipelineDataIn, intention_nodes: intentionNodes, sap_operation: operationType, sap_service: serviceName, sap_connection: connection, sap_payload: data } }];

const data = $json;
const { language, sap_operation, sap_service, sap_connection, sap_payload, active_node_id, intention_nodes } = data;
const { process_definition, form_state } = (intention_nodes || {})[active_node_id] || {};

let chatInput;

if (sap_operation === 'CALL_FUNCTION') {
  // A fixed, mechanical, entity-bound OData function call -- e.g. executing an
  // already-registered SQLQueries lookup (SAP's own workaround for reading a table that
  // isn't exposed as a first-class Service Layer entity). No RESOLVABLE FIELDS/filter-building
  // judgment needed, unlike GET_SINGLE/GET_QUERY -- data.sap_call_config carries everything
  // literally, set directly by the caller (not derived from a registered process_definition,
  // since this call isn't tied to one).
  const { service_name: callService, function_name: callFunction, entity_key: entityKey, params: callParams } = data.sap_call_config || {};
  chatInput = `Call sap_call_function with these exact parameters, unmodified:

CALL:
{
  "serviceName": "${callService}",
  "functionName": "${callFunction}",
  "entityKey": ${JSON.stringify(entityKey)},
  "parameters": ${JSON.stringify(callParams || {})},
  "connection": ${JSON.stringify(sap_connection)}
}

Success: {"status": "success", "message": "Done.", "form_state": null, "processes": null}
Error: {"status": "error", "message": "<user-friendly Markdown in ${language}>", "form_state": null, "processes": null}`;
} else if (sap_operation === 'GET_SINGLE') {
  const keySapField = process_definition.query.key.sap_field;
  const keyValue = form_state[process_definition.query.key.id];
  const expand = process_definition.query.expand || [];
  const expandLine = expand.length ? `  "expand": ${JSON.stringify(expand)},\n` : '';
  const wantsJson = form_state.response_format === 'json';
  const successInstruction = wantsJson
    ? `a fenced \`\`\`json code block in the message field containing the full result (after removing null fields) as raw JSON -- NOT a bullet list or prose`
    : `Markdown result in ${language}, remove null fields, use schema labels`;
  chatInput = `Call sap_entity_get with these exact parameters:

CALL:
{
  "serviceName": "${sap_service}",
  "entitySet": "",
  "keyValues": { "${keySapField}": ${JSON.stringify(keyValue)} },
${expandLine}  "connection": ${JSON.stringify(sap_connection)}
}

Success: {"status": "success", "message": "<${successInstruction}>", "form_state": null, "processes": null}
Not found / Error: {"status": "error", "message": "<user-friendly Markdown in ${language}>", "form_state": null, "processes": null}`;
} else if (sap_operation === 'GET_QUERY') {
  const queryDef = process_definition.query;
  const schemaDef = process_definition.schema_definition;
  const defaultSelect = Array.isArray(queryDef.select) && queryDef.select.length
    ? queryDef.select
    : schemaDef?.list_select?.length ? schemaDef.list_select
    : schemaDef?.get_select?.length ? schemaDef.get_select
    : null;
  // Case-insensitive matching is handled by the SAP MCP tool itself (a Service Layer
  // request header), not by this template -- filters built here stay plain OData v2.
  // LITERAL_BUILDERS below compares default_filters/enum-style eq/ne against exact
  // system values (e.g. CardType eq 'cSupplier'), never user-typed text.
  const STRING_FILTER_BUILDERS = {
    contains: (field, v) => `substringof('${v}', ${field})`,
    not_contains: (field, v) => `not substringof('${v}', ${field})`,
    startswith: (field, v) => `startswith(${field}, '${v}')`,
    not_startswith: (field, v) => `not startswith(${field}, '${v}')`,
    endswith: (field, v) => `endswith(${field}, '${v}')`,
    not_endswith: (field, v) => `not endswith(${field}, '${v}')`,
    eq: (field, v) => `${field} eq '${v}'`,
    ne: (field, v) => `${field} ne '${v}'`,
  };
  const LITERAL_BUILDERS = {
    eq: (field, v) => `${field} eq ${typeof v === 'string' ? `'${v}'` : v}`,
    ne: (field, v) => `${field} ne ${typeof v === 'string' ? `'${v}'` : v}`,
  };
  // default_filters express an intrinsic property of the process itself (e.g. "vendor_list
  // only ever means CardType eq 'cSupplier'") -- mandatory, never something the user's own
  // filter combination can override or omit, so they're always ANDed in regardless of match_all.
  const defaultFilterExprs = (queryDef.default_filters || []).map(f => {
    const builder = LITERAL_BUILDERS[f.operator] || LITERAL_BUILDERS.eq;
    return builder(f.sap_field, f.value);
  });
  const parsesAsFiniteNumber = (val) => {
    if (typeof val === 'number') return Number.isFinite(val);
    if (typeof val === 'string') return val.trim() !== '' && Number.isFinite(Number(val));
    return false;
  };
  // A resolve block hands per-field judgment to the agent (name vs. code can't be told apart
  // deterministically for anything but an already-numeric value) -- see RESOLVABLE FIELDS below.
  // The one exception code keeps for itself: a number-typed resolve field whose value already
  // parses as a finite number is unambiguous, so it flows straight through as a direct filter,
  // same as any non-resolve field, with zero agent judgment involved.
  const presentFilters = (queryDef.filters || [])
    .filter(f => form_state[f.id] !== null && form_state[f.id] !== undefined);
  const takesFastPath = (f) => !!f.resolve && (f.type === 'number' || f.type === 'integer') && parsesAsFiniteNumber(form_state[f.id]);
  const directFilters = presentFilters.filter(f => !f.resolve || takesFastPath(f));
  const resolvableFields = presentFilters.filter(f => f.resolve && !takesFastPath(f));
  const definitionHasResolve = (queryDef.filters || []).some(f => f.resolve);
  const resolvedFilters = directFilters
    .map(f => {
      const val = form_state[f.id];
      // operator is declared as an array of allowed operator names (even a single allowed
      // operator is a 1-element array); form_state.<id>_operator is the agent's per-turn
      // pick among them, falling back to the first declared one when the field only has
      // one option or none was chosen. A bare string is normalized here too, for any
      // process definition that hasn't been migrated to the array form yet.
      const allowedOperators = Array.isArray(f.operator) ? f.operator : [f.operator];
      const chosen = form_state[`${f.id}_operator`];
      const operator = allowedOperators.includes(chosen) ? chosen : allowedOperators[0];

      if (f.type === 'date') return `${f.sap_field} ${operator} datetime'${val}T00:00:00'`;

      if (f.type === 'string') {
        const builder = STRING_FILTER_BUILDERS[operator] || STRING_FILTER_BUILDERS.eq;
        const parts = String(val).split(/,|\bor\b/i).map(p => p.trim()).filter(p => p);
        if (parts.length <= 1) return builder(f.sap_field, parts[0] || val);
        const conds = parts.map(p => builder(f.sap_field, p));
        // Multiple values: a positive match reads naturally as OR ("matches A or B"); a
        // negated match reads naturally as AND ("excludes both A and B" -- an OR of two
        // negations is almost always true and wouldn't filter anything out).
        return '(' + conds.join(operator.startsWith('not_') ? ' and ' : ' or ') + ')';
      }

      return `${f.sap_field} ${operator} ${val}`;
    });
  // Parenthesize the user's own filter group before ANDing it with default_filters -- otherwise
  // "or"'s lower precedence than "and" would silently detach the last clause (e.g. "A or B and
  // CardType eq 'cSupplier'" parses as "A or (B and CardType eq 'cSupplier')", not "(A or B) and
  // CardType eq 'cSupplier'").
  const userFilterExpr = resolvedFilters.length
    ? resolvedFilters.length > 1
      ? '(' + resolvedFilters.join(form_state.match_all ? ' and ' : ' or ') + ')'
      : resolvedFilters[0]
    : null;
  const finalFilterExpr = [...defaultFilterExprs, ...(userFilterExpr ? [userFilterExpr] : [])].join(' and ') || null;
  // A resolved alternate-key lookup expects exactly one match -- force top to 1 regardless
  // of any other default, rather than trusting the filter above to be the only constraint.
  const effectiveTop = form_state.top || queryDef.top || 20;
  const effectiveSkip = form_state.skip || 0;
  const effectiveOrderBy = form_state.order_by || queryDef.order_by;
  const requestedFields = form_state.requested_fields || form_state.select_fields;
  const fieldMap = (schemaDef?.fields || []).map(f => ({ label: f.label, sap_field: f.sap_field }));
  const resolvableSection = resolvableFields.length
    ? `RESOLVABLE FIELDS (each value below may be a human-readable name instead of the actual SAP code -- for each field, first judge whether its given value already looks like a valid code/id for a field of that type. If so, build "<sap_field> <operator> <value>" yourself per the OData v2 FILTER SYNTAX RULES below and AND it into the final filter alongside PRE-BUILT FILTERS -- no lookup needed. If instead it looks like a human-readable name, first call sap_query_entity_set against the field's resolve.service, filtering resolve.match_field resolve.match_type <value> (ANDing in resolve.default_filters the same way default_filters are ANDed in elsewhere), extract resolve.return_field from the result, then build the clause using that resolved value the same way. On 0 or more than 1 match, stop -- do NOT call the main query -- reply using the graceful error format instead, naming what was searched for and, on multiple matches, listing the candidates so the user can pick.):
${resolvableFields.map(f => {
        const label = (schemaDef?.fields || []).find(sf => sf.sap_field === f.sap_field)?.label || f.id;
        const allowedOperators = Array.isArray(f.operator) ? f.operator : [f.operator];
        const val = form_state[f.id];
        const r = f.resolve || {};
        return `- ${label} (${f.sap_field}): operator(s) ${JSON.stringify(allowedOperators)}, type ${f.type}, value as given: ${JSON.stringify(val)}
  resolve: service ${JSON.stringify(r.service)}, match_field ${JSON.stringify(r.match_field)}, match_type ${JSON.stringify(r.match_type || 'contains')}, return_field ${JSON.stringify(r.return_field)}, default_filters ${JSON.stringify(r.default_filters || [])}`;
      }).join('\n')}

`
    : '';
  const wantsJson = form_state.response_format === 'json';
  const successInstruction = wantsJson
    ? `a fenced \`\`\`json code block in the message field containing the results as a raw JSON array (using schema field ids as keys) -- NOT a Markdown table`
    : `Markdown table in ${language}`;
  const filterVerbatimLine = 'The pre-built filters above already follow this syntax. Pass them to the filter parameter verbatim.' +
    (resolvableFields.length ? ' Combine whatever you build or resolve for RESOLVABLE FIELDS with PRE-BUILT FILTERS via AND before calling the tool.' : '');
  const rawQueryDefPreamble = 'RAW QUERY DEFINITION (authoritative source the filters above were derived from -- cross-check it: if its default_filters or filters declare a constraint not already reflected in PRE-BUILT FILTERS above, you MUST still AND it in yourself before calling the tool):' +
    (definitionHasResolve ? ' Only perform a lookup when explicitly told to via a RESOLVABLE FIELDS section above -- a resolve key appearing in this raw JSON dump alone is not an instruction to look anything up.' : '');
  chatInput = `Call sap_query_entity_set with these parameters.

SERVICE: ${sap_service}
CONNECTION: ${JSON.stringify(sap_connection)}
PRE-BUILT FILTERS (apply as-is, already valid OData v2 -- already includes this process's mandatory default_filters, ANDed in): ${finalFilterExpr || 'none'}
${resolvableSection}DEFAULT SELECT: ${defaultSelect ? JSON.stringify(defaultSelect) : 'omit'}
TOP: ${effectiveTop}
SKIP: ${effectiveSkip || 'omit'}
ORDERBY: ${effectiveOrderBy ? effectiveOrderBy.map(o => o.field + ' ' + o.direction).join(',') : 'omit'}

USER REQUESTED FIELDS: ${requestedFields ? JSON.stringify(requestedFields) : '"default"'}
If the user specified fields, use this label->sap_field map to resolve them:
${JSON.stringify(fieldMap)}
If default or none specified, use DEFAULT SELECT above.

OData v2 FILTER SYNTAX RULES (SAP B1S):
- String contains: substringof('value', FieldName) -- NEVER use FieldName contains 'value'
- String equals: FieldName eq 'value'
- Number equals: FieldName eq 123
- Multiple OR: (substringof('a', F) or substringof('b', F))
- AND: expr1 and expr2
${filterVerbatimLine}

${rawQueryDefPreamble}
${JSON.stringify(queryDef)}

RULES:
- Omit any parameter that is null, empty, or undefined.
- Never pass null values to any parameter.
- Use default select unless user explicitly requested specific fields.
- Render results as a Markdown table using schema labels as column headers, UNLESS the user explicitly asked for JSON/raw format (see OUTPUT below) -- in that case render a fenced \`\`\`json code block instead.

Success: {"status": "success", "message": "<${successInstruction}>", "form_state": null, "processes": null}
No records: {"status": "success", "message": "<no records message in ${language}>", "form_state": null, "processes": null}
Error: {"status": "error", "message": "<user-friendly Markdown in ${language}>", "form_state": null, "processes": null}`;
} else {
  // POST_CREATE
  const outputParsing = process_definition?.output_parsing;
  const successMsg = process_definition?.output?.success_message || 'Operation completed successfully.';
  const fieldReference = (process_definition?.form?.sections || []).flatMap(
    (section) => (section.fields || []).map(({ sap_field, label, ask }) => ({ sap_field, label, ask })),
  );
  const outputParsingSection = outputParsing
    ? `## OUTPUT PARSING SPEC\n${JSON.stringify(outputParsing, null, 2)}\n\n## HOW TO BUILD THE SUCCESS MESSAGE\n- Extract every field listed in output_parsing.fields from the SAP response body.\n- Follow output_parsing.instruction exactly to decide what to display and how to format it.\n- Use this as the base success message template: "${successMsg}"\n- When the instruction says to display lines/items as a table, ALWAYS use proper Markdown table syntax -- include the header row, the separator row (|---|---|...|), and one data row per item.`
    : `## SUCCESS MESSAGE TEMPLATE\n${successMsg}\n(No output_parsing spec available -- fill any {placeholder} in the template with the matching value from the SAP response body.)`;
  chatInput = `Call sap_entity_create with these exact parameters. Do not modify anything:

CALL:
{
  "serviceName": "${sap_service}",
  "entitySet": "",
  "data": ${JSON.stringify(sap_payload)},
  "connection": ${JSON.stringify(sap_connection)}
}

${outputParsingSection}

## FIELD REFERENCE (use only to interpret an error below -- sap_field is the exact name SAP's error text will reference)
${JSON.stringify(fieldReference)}

Return ONLY one of these JSON objects (no markdown, no extra text):
Success: {"status": "success", "message": "<formatted success message in ${language}>", "form_state": null, "processes": null}
Error:   {"status": "error", "message": "<in ${language}: explain what went wrong using the actual SAP error text -- if, and only if, that error text clearly names one of the fields in FIELD REFERENCE (by its sap_field name or an unambiguous match), name it using that field's label and invite the user to provide or correct it using that field's own 'ask' question; otherwise relay the SAP error's essential meaning in plain language without guessing which field caused it>", "form_state": null, "processes": null}`;
}

return [{ json: { ...data, chatInput } }];

const base = $json;
const content = base._parsed || {};

// Structural capture of the record a document-eligible GET_SINGLE fetch actually returned --
// generate-document.json's field-mapping schema reads real SAP field names out of form_state,
// so this needs the complete raw record, not the agent's own formatted message. Two earlier
// approaches both failed live: asking the model to transcribe the COMPLETE record blew its
// output-token budget and truncated mid-response; asking for a null-stripped copy still had
// the model silently drop an entire nested sub-object (BusinessPartner) while "transcribing".
// Reading Agent: Execute's own intermediateSteps (enabled via options.returnIntermediateSteps)
// sidesteps the model's output path entirely -- this is the tool's actual response, structural
// and complete, immune to both failure modes and to any future growth in entity size.
const extractToolResult = (marker) => {
  try {
    const steps = base.intermediateSteps || [];
    const step = steps[steps.length - 1];
    if (!step) return null;
    const outer = JSON.parse(step.observation);
    const text = outer[0]?.response?.[0]?.text || '';
    const idx = text.indexOf(marker);
    if (idx === -1) return null;
    return JSON.parse(text.slice(idx + marker.length).trim());
  } catch (e) {
    return null;
  }
};
// Finds and parses the first complete, balanced JSON value at the start of `text`, ignoring
// any trailing non-JSON content -- unlike extractToolResult's own JSON.parse(whole
// remainder), which only works when nothing follows the value (true for sap_entity_get's
// "Entity data:", but never for queryEntitySet's "Data:" marker, which always appends a
// "Query parameters used:" footer whenever any parameter -- e.g. the $filter this whole path
// exists for -- was actually used).
const parseJsonPrefix = (text) => {
  const trimmed = text.trimStart();
  const opener = trimmed[0];
  const closer = opener === '[' ? ']' : opener === '{' ? '}' : null;
  if (!closer) return null;
  let depth = 0;
  let inString = false;
  let escaped = false;
  for (let i = 0; i < trimmed.length; i++) {
    const char = trimmed[i];
    if (inString) {
      if (escaped) escaped = false;
      else if (char === '\\') escaped = true;
      else if (char === '"') inString = false;
      continue;
    }
    if (char === '"') { inString = true; continue; }
    if (char === opener) depth++;
    else if (char === closer) {
      depth--;
      if (depth === 0) {
        try { return JSON.parse(trimmed.slice(0, i + 1)); } catch (e) { return null; }
      }
    }
  }
  return null;
};
// queryEntitySet's own "Data:\n" marker (da-sap-mcp query/handler.ts) -- reached whenever a
// document-eligible lookup resolves via a $filter rather than a direct key GET (e.g. the user
// gave a DocNum against a schema whose real key is DocEntry, per that schema's own "note").
// Its record(s) come back wrapped in an array (JSON.stringify(shown, ...), shown = an array
// even for a single match) and, critically, with every nested-array field already stripped
// by the tool itself (HQuery.__stripNestedArrays) before this text was ever produced -- there
// is no way to recover those from this text at all. Taking records[0] still fixes every
// header-level field a document needs; line items stay unpopulated for this path specifically
// until a real follow-up GET_SINGLE-by-resolved-key call is added -- not implemented yet.
const extractQueryFirstRecord = () => {
  try {
    const steps = base.intermediateSteps || [];
    const step = steps[steps.length - 1];
    if (!step) return null;
    const outer = JSON.parse(step.observation);
    const text = outer[0]?.response?.[0]?.text || '';
    const idx = text.indexOf('Data:\n');
    if (idx === -1) return null;
    const records = parseJsonPrefix(text.slice(idx + 'Data:\n'.length));
    return Array.isArray(records) && records.length > 0 ? records[0] : null;
  } catch (e) {
    return null;
  }
};
const extractFetchedEntity = () => extractToolResult('Entity data:') ?? extractQueryFirstRecord();
// sap_call_function's own response formatting (da-sap-mcp query/handler.ts) uses "Result:\n"
// instead of sap_entity_get's "Entity data:\n" -- same mechanism, different marker.
const extractCallFunctionResult = () => extractToolResult('Result:');


let needsErrorParse = false;
let errorCode = null;
let errorMessage = null;

const intentionNodesIn = base.intention_nodes || {};
const activeNode = intentionNodesIn[base.active_node_id] || {};
let formState = activeNode.form_state;
let intentionNodes = intentionNodesIn;
let activeNodeId = base.active_node_id;

// Only set on the success branch -- reset_process still matters for Django's
// active_node_id/last_bot_message resettable merge (main.py's _merge_field); the
// process_id/process_definition/form_state root-level copies this flag used to force
// through are gone entirely now, intention_nodes[id] was always the only real copy.
let resetProcess = false;

if (content.status === 'success') {
  // Done -- nothing left pending for this intent. The node itself is marked 'completed'
  // (an empty result set is still a completed inquiry, not still-active). active_node_id
  // itself moves on below (auto-resume to whatever this interrupted) -- Park Current
  // Intent no longer needs active_node_id left on a completed node to find its parent,
  // since a completed node's own parent_id (set at creation time) is enough on its own.
  // The node's own form_state already holds what was actually submitted -- a completed
  // node should keep a record of what it submitted, not go blank the instant it finishes.
  // error_detail (if this same node failed on a prior attempt) is explicitly cleared here
  // so a later general-inquiry lookup of this now-completed node never cites a stale error
  // for a request that has since succeeded.
  // A node reaching 'completed' here never re-enters form-filling or SAP execution
  // again (only ever read for display -- Intention Graph, general-inquiry context), so
  // its full process_definition (the whole form schema plus schema_definition) is no
  // longer needed -- prune to just .name, same stub shape register-intention-node.json's
  // Register Node already uses when a batch record registers straight into 'completed'.
  // document_type/document_mapping are schema-level facts (see generate-document.json's
  // Resolve Target Node) a query like ar_invoice_get needs to keep even after completing here
  // -- this is a second, independent completed-node pruning site parallel to
  // register-intention-node.json's Register Node (same stub-shape convention), found live
  // when a real ar_invoice_get -> generate_document chase came up empty-handed because this
  // copy wasn't included in that earlier fix.
  const schemaDefinition = activeNode.process_definition?.schema_definition || {};
  const documentType = schemaDefinition.document_type ?? activeNode.process_definition?.document_type ?? null;
  const documentMapping = schemaDefinition.document_mapping ?? activeNode.process_definition?.document_mapping ?? null;
  // content.form_state is null for every non-document-eligible fetch (Build Execution
  // Prompt only asks the agent to fill it in for a GET_SINGLE whose schema declares
  // document_type) -- falling back to the pre-call activeNode.form_state preserves today's
  // behavior (e.g. a query's own input params) for everything else.
  const fetchedEntity = (
    (base.sap_operation === 'GET_SINGLE' || base.sap_operation === 'GET_QUERY')
    && (activeNode.process_definition?.schema_definition?.document_type ?? activeNode.process_definition?.document_type)
  ) ? extractFetchedEntity() : null;
  intentionNodes = base.active_node_id && intentionNodesIn[base.active_node_id]
    ? { ...intentionNodesIn, [base.active_node_id]: {
        ...activeNode,
        status: 'completed',
        error_detail: null,
        form_state: fetchedEntity || activeNode.form_state,
        process_definition: {
          name: activeNode.process_definition?.name ?? null,
          ...(documentType ? { document_type: documentType } : {}),
          ...(documentMapping ? { document_mapping: documentMapping } : {}),
        },
      } }
    : intentionNodesIn;
  // Auto-resume: this intent interrupted whatever was active before it (Park Current
  // Intent set this node's own parent_id to that node's id at creation time) -- now that
  // it's done, hand control back rather than leaving active_node_id stranded on a node
  // that will never execute again. Walks past any ancestor that's ALSO already terminal
  // (shouldn't normally happen -- a paused node can't independently finish while this one
  // was running -- but stays defensive). Same TERMINAL_STATUSES/walk shape duplicated in
  // Park Current Intent (intent-manager.json), Compute Form Outcome
  // (sap-process-form-filling.json), Classify & Store Error (error-parser.json), and
  // Resolve Final State (batch-processing.json) -- keep all five in sync if this changes.
  const TERMINAL_STATUSES = new Set(['completed', 'abandoned']);
  const findResumeTarget = (nodeId, nodes) => {
    let current = nodeId;
    while (current) {
      const node = nodes[current];
      if (!node) return null;
      if (!TERMINAL_STATUSES.has(node.status)) return current;
      current = node.parent_id;
    }
    return null;
  };
  const resumeTargetId = findResumeTarget(activeNode.parent_id, intentionNodes);
  if (resumeTargetId) {
    intentionNodes = { ...intentionNodes, [resumeTargetId]: { ...intentionNodes[resumeTargetId], status: 'active' } };
  }
  activeNodeId = resumeTargetId;
  resetProcess = true;
} else {
  // A graceful 'error' status, or anything unparseable/unrecognized -- SAP didn't accept
  // the submission. form_state.ready flips back to false so the NEXT turn's Agent: Find
  // still sees an active, mid-form process to resolve against -- Agent: Intent Finder is
  // what decides, from the user's next message, whether that's a correction to retry or
  // an abandon-and-switch-intent.
  // No same-turn bounce-back to the caller: SAP MCP failures surface as an agent-node
  // failure (Has Agent Error?), not a graceful status, often enough that trying to
  // distinguish "correctable" from "hard failure" here would be unreliable anyway --
  // simpler and more robust to always deliver and let the next turn decide.
  needsErrorParse = true;
  errorCode = 'SAP_ERROR';
  errorMessage = content.message || null;
  formState = { ...(formState || {}), ready: false };
  // Node stays 'active' (needs correcting, not abandoned), but its saved copy must track
  // the ready:false flip too, or the next turn's Prompt: Intention Focus still sees a
  // stale ready:true snapshot for a node that's actually back in an editable state.
  // error_detail is also mirrored onto the node itself (not just this turn's ephemeral
  // error/error_message) so a later turn -- e.g. Prompt: Context & Conversation's
  // lastFailedNode/activeNode lookup, or Agent: Form resuming this same node -- can still
  // answer "what went wrong" even after the turn that produced the error has passed.
  intentionNodes = base.active_node_id && intentionNodesIn[base.active_node_id]
    ? { ...intentionNodesIn, [base.active_node_id]: { ...activeNode, form_state: formState, error_detail: errorMessage } }
    : intentionNodesIn;
}

return [{ json: {
  ...base,
  message: content.message ?? base.message,
  active_node_id: activeNodeId,
  intention_nodes: intentionNodes,
  reset_process: resetProcess,
  _needs_error_parse: needsErrorParse,
  // CALL_FUNCTION is a one-off helper call, never tied to a registered intention_node (the
  // caller passes active_node_id: null for it, so the completion/auto-resume logic above is
  // already a no-op) -- its result surfaces here instead, structurally captured the same way
  // GET_SINGLE's document-eligible fetch already is, immune to the same transcription
  // failure modes (token-budget truncation, silently dropped nested data).
  ...(base.sap_operation === 'CALL_FUNCTION' && content.status === 'success'
    ? { _sap_call_result: extractCallFunctionResult() }
    : {}),
  ...(needsErrorParse ? { error: errorCode, error_message: errorMessage } : {}),
} }];
